          "proof": "ai-generated"
        },
        "sources": {
          "references": [
            {
              "title": "Steven G. Krantz, Foundations of Analysis, §1.2",
              "url": "https://api.pageplace.de/preview/DT0400.9781482220759_A37871115/preview-9781482220759_A37871115.pdf"
            }
          ]
        }
      },
      {
        "id": "thm-dyadic-square-root-bisection-encloses",
        "kind": "theorem",
        "title": "Dyadic square-root bisection gives outward endpoints",
        "deps": [
          "alg-dyadic-square-root-bisection",
          "lem-directed-dyadic-rounding-enclosure-and-error",
          "lem-nonnegative-square-root-exists-and-unique"
        ],
        "statement": "For every nonnegative exact dyadic input $x$ and $n\\ge1$, the exact dyadic\npair returned by [[alg-dyadic-square-root-bisection]] contains $\\sqrt{x}$ and\nhas width $2^{\\lfloor j/2\\rfloor-n}$ when $x>0$, where $j$ is the exponent\nselected by that algorithm. Storing the endpoints after outward rounding\npreserves enclosure, although storage rounding may increase the width.\nFor fixed $n$, both exact endpoint functions are nondecreasing in $x\\ge0$;\ndirected storage rounding preserves that monotonicity.",
        "dependency_level": 3,
        "strategy": "direct",
